(() => {
'use strict';
const el=id=>document.getElementById(id);
const status=el('status'), summary=el('summary'), results=el('results'), refresh=el('refresh');
let table=null, columns=null, stale=false, ready=false;
function norm(s){return String(s||'').toLowerCase().replace(/[_-]/g,' ').replace(/\s+/g,' ').trim();}
function findField(fields, test, label){const found=fields.filter(f=>test(norm(f.key)+' '+norm(f.label),f));if(found.length!==1)throw new Error('Cannot unambiguously identify '+label+' in the saved schema. Please review the table fields.');return found[0];}
function inspect(body){if(!body||body.kind!=='structured_table'||!Array.isArray(body.fields)||!Array.isArray(body.rows))throw new Error('The scoped read did not return a structured comparison table.');const f=body.fields;return {cost:findField(f,(s,f)=>['decimal','integer'].includes(f.type)&&/cost|price|hire|budget/.test(s),'hire cost'),capacity:findField(f,(s,f)=>['integer','decimal'].includes(f.type)&&/capacity/.test(s),'capacity'),access:findField(f,s=>/step\s*free/.test(s),'step-free access')};}
function cell(row,key){const c=(Array.isArray(row.cells)?row.cells:[]).find(c=>c.field_key===key);return c?c.value:null;}
function num(v){if(v===null||v===undefined||v===''||typeof v==='boolean')return null;const n=Number(v);return Number.isFinite(n)?n:null;}
function yes(v){if(v===true)return true;if(v===false)return false;if(typeof v==='string'){const s=norm(v);if(['yes','true','step free','accessible'].includes(s))return true;if(['no','false','not step free','not accessible'].includes(s))return false;}return null;}
function display(v,f){if(v===null||v===undefined)return 'Not supplied';if(typeof v==='boolean')return v?'Yes':'No';if(f.type==='decimal'){const n=num(v);if(n!==null&&Number.isInteger(f.scale)&&f.scale>=0&&f.scale<=6)return n.toFixed(f.scale);}return String(v);}
function render(){results.replaceChildren();if(!table){summary.textContent='Count unavailable until saved data is loaded.';return;}const budget=Number(el('budget').value),capacity=Number(el('capacity').value);if(el('budget').value.trim()===''||el('capacity').value.trim()===''||!Number.isFinite(budget)||budget<0||!Number.isFinite(capacity)||capacity<0||!Number.isInteger(capacity)){summary.textContent='Enter a non-negative budget and a whole-number minimum capacity.';return;}const needAccess=el('stepfree').checked;let missing=0;const matches=table.rows.filter(row=>{const cost=num(cell(row,columns.cost.key)),cap=num(cell(row,columns.capacity.key)),access=yes(cell(row,columns.access.key));if(cost===null||cap===null||(needAccess&&access===null)){missing++;return false;}return cost<=budget&&cap>=capacity&&(!needAccess||access===true);});summary.textContent=(stale?'Previously loaded data only — refresh failed. ':'')+matches.length+' matching '+(matches.length===1?'venue':'venues')+' of '+table.rows.length+' at ≤£'+budget.toFixed(2)+', capacity ≥'+capacity+' people'+(needAccess?', step-free required.':', step-free not required.')+(matches.length===0?' No venue qualifies under these controls. Try increasing the budget, or seek a confirmed discount/other venue; do not treat a hypothetical discount as a saved price.':'')+(missing?' '+missing+' row(s) have missing or unrecognized required facts and are excluded.':'');const nameField=table.fields.find(f=>f.type==='text'&&/venue|name/.test(norm(f.key)+' '+norm(f.label)));for(const row of matches){const card=document.createElement('article');card.className='card';const heading=document.createElement('h3');heading.textContent=nameField?display(cell(row,nameField.key),nameField):'Venue '+row.row_id;card.append(heading);const dl=document.createElement('dl');for(const f of table.fields){const dt=document.createElement('dt');dt.textContent=f.label+(f.unit?' ('+f.unit+')':'');const dd=document.createElement('dd');dd.textContent=display(cell(row,f.key),f);dl.append(dt,dd);}card.append(dl);results.append(card);}}
async function read(){if(!ready)return;refresh.disabled=true;status.className='';status.textContent='Reading the bound saved comparison…';try{const response=await window.workagent.request('refresh_venues',{});if(!response||response.artifact_id!=='167c057f-3ff9-432a-930c-0bdc46841664'||response.revision_id!=='3067f3b4-8877-49cf-9778-ce6817dade1c'||response.body_hash!=='7c73a116f9d5c153f7937b01a18ef14b6f9483979ed0056fc5485245561154de')throw new Error('The read did not match this view’s bound revision.');const cols=inspect(response.body);table=response.body;columns=cols;stale=false;el('revision').textContent='Saved revision: '+response.revision_id;el('savedNotes').replaceChildren();for(const note of table.notes||[]){const p=document.createElement('p');p.textContent=String(note);el('savedNotes').append(p);}status.textContent='Loaded the exact bound saved revision. Controls only filter locally; no edits are saved.';render();}catch(error){stale=!!table;status.className='error';status.textContent='Saved-data read failed or was refused/stale. '+String(error&&error.message||error)+(table?' Previously loaded data remains visible and is not freshly loaded.':' No saved data has been loaded; matches are unavailable.')+' If the table revision changed, request a newly bound view.';render();}finally{refresh.disabled=false;}}
for(const id of ['budget','capacity','stepfree'])el(id).addEventListener('input',render);
refresh.addEventListener('click',read);
refresh.disabled=true;
(async()=>{try{await window.workagent.ready();ready=true;await read();}catch(error){status.className='error';status.textContent='View initialization failed. No saved data loaded. '+String(error&&error.message||error);summary.textContent='Count unavailable. Reopen the saved comparison table.';}})();
})();
